export class ProductionComponent implements OnInit {
  private readonly http = inject(HttpClient);
  private readonly fb = inject(FormBuilder);
  private readonly messages = inject(MessageService);
  protected readonly auth = inject(AuthService);
  protected readonly consolidations = signal<ProductionConsolidation[]>([]);
  protected readonly stockRequests = signal<StockReplenishmentRequest[]>([]);
  protected readonly summary = signal<ProductionSummaryRow[]>([]);
  protected readonly areas = signal<ProductionArea[]>([]);
  protected readonly categories = signal<ProductCategory[]>([]);
  protected readonly selected = signal<ProductionConsolidation | null>(null);
  protected readonly plantConsolidations = signal<ProductionConsolidation[]>([]);
  protected readonly selectedDetail = signal<ProductionConsolidationDetail | null>(null);
  protected readonly history = signal<ProductionHistory[]>([]);
  protected readonly view = signal<ProductionView>('planning');
  protected readonly loading = signal(false);
  protected readonly saving = signal(false);
  protected readonly planningCount = signal(0);
  protected readonly planningPage = signal(1);
  protected readonly planningPageSize = signal(30);
  protected readonly planningTotal = signal(0);
  protected readonly dateFilter = signal('');
  protected readonly areaFilter = signal<string | null>(null);
  protected readonly categoryFilter = signal<string | null>(null);
  protected readonly statusFilter = signal<ProductionConsolidationStatus[]>([...DEFAULT_PLANNING_STATUSES]);
  protected readonly generationDialog = signal(false);
  protected readonly requestGenerationDialog = signal(false);
  protected readonly detailDialog = signal(false);
  protected readonly planDialog = signal(false);
  protected readonly deliveryDialog = signal(false);
  protected readonly areaDialog = signal(false);
  protected readonly historyDialog = signal(false);
  protected readonly reasonDialog = signal(false);
  protected readonly reasonAction = signal<ReasonAction>('detail');
  protected readonly editingAreaId = signal<string | null>(null);
  protected readonly selectedStockRequest = signal<StockReplenishmentRequest | null>(null);
  protected readonly statusOptions = [{ label: 'Borrador', value: 'BORRADOR' }, { label: 'Emitida', value: 'EMITIDA' }, { label: 'En proceso', value: 'EN_PROCESO' }, { label: 'Completada', value: 'CERRADA' }, { label: 'Completada con faltantes', value: 'CERRADA_INCOMPLETA' }, { label: 'Cancelada', value: 'CANCELADA' }];
  protected readonly recordStatusOptions = [{ label: 'Activo', value: 'ACTIVO' }, { label: 'Inactivo', value: 'INACTIVO' }];
  protected readonly generationForm = this.fb.nonNullable.group({ deliveryDate: ['', Validators.required] });
  protected readonly requestGenerationForm = this.fb.nonNullable.group({ deliveryDate: ['', Validators.required] });
  protected readonly planForm = this.fb.nonNullable.group({ scheduledDate: ['', Validators.required], sequence: [1, [Validators.required, Validators.min(1)]], additionalQuantity: [0, [Validators.required, Validators.min(0)]], reason: [''] });
  protected readonly reasonForm = this.fb.nonNullable.group({ reason: ['', [Validators.required, Validators.minLength(5)]] });
  protected readonly deliveryForm = this.fb.nonNullable.group({ quantity: [0, [Validators.required, Validators.min(0.000001)]], incident: [''] });
  protected readonly areaForm = this.fb.nonNullable.group({ name: ['', Validators.required], status: ['ACTIVO'], categoryIds: this.fb.nonNullable.control<string[]>([]) });

  ngOnInit(): void { if (this.auth.can('production.areas.read')) { this.loadAreas(); this.loadCategories(); } if (this.auth.can('production.consolidations.create')) this.loadStockRequests(false); if (this.auth.can('production.consolidations.read')) this.loadConsolidations(); }
  protected setView(view: ProductionView): void { this.view.set(view); if (view !== 'tracking') this.reload(); }
  protected reload(): void { if (this.view() === 'requests') this.loadStockRequests(); else if (this.view() === 'plant') this.loadPlantBoard(); else if (this.view() === 'summary') this.loadSummary(); else if (this.view() === 'areas') { this.loadAreas(); this.loadCategories(); } else this.loadConsolidations(); }
  private params(): HttpParams { const planning = this.view() === 'planning'; let params = new HttpParams().set('page', planning ? this.planningPage() : 1).set('limit', planning ? this.planningPageSize() : 100); if (!planning && this.dateFilter()) params = params.set('deliveryDate', this.dateFilter()); if (!planning && this.areaFilter()) params = params.set('productionAreaId', this.areaFilter()!); if (!planning && this.categoryFilter()) params = params.set('categoryId', this.categoryFilter()!); if (planning && this.statusFilter().length) params = params.set('statuses', this.statusFilter().join(',')); return params; }
  private loadConsolidations(): void { this.loading.set(true); const requirementsOnly = this.auth.can('production.requirements.read') && !this.auth.can('production.consolidations.create') && !this.auth.can('production.plan.adjust'); const endpoint = requirementsOnly ? '/api/production-requirements' : '/api/production-consolidations'; this.http.get<Paginated<ProductionConsolidation>>(endpoint, { params: this.params() }).subscribe({ next: (response) => { this.consolidations.set(response.data); if (this.view() === 'planning') { this.planningPage.set(response.meta.page); this.planningPageSize.set(response.meta.limit); this.planningTotal.set(response.meta.total); } this.loading.set(false); this.loadPlanningCount(endpoint); }, error: (error) => this.fail(error) }); }
  protected applyPlanningFilters(): void { this.planningPage.set(1); this.loadConsolidations(); }
  protected onPlanningPage(event: TableLazyLoadEvent): void { const rows = event.rows ?? this.planningPageSize(); const first = event.first ?? 0; this.planningPageSize.set(rows); this.planningPage.set(Math.floor(first / rows) + 1); this.loadConsolidations(); }
  private loadPlanningCount(endpoint?: string): void { if (!this.auth.can('production.consolidations.read')) return; const path = endpoint ?? (this.auth.can('production.requirements.read') && !this.auth.can('production.consolidations.create') && !this.auth.can('production.plan.adjust') ? '/api/production-requirements' : '/api/production-consolidations'); const params = new HttpParams().set('limit', 1).set('statuses', DEFAULT_PLANNING_STATUSES.join(',')); this.http.get<Paginated<ProductionConsolidation>>(path, { params }).subscribe({ next: (response) => this.planningCount.set(response.meta.total) }); }
  protected loadStockRequests(showLoading = true): void { if (showLoading) this.loading.set(true); this.http.get<StockReplenishmentRequest[]>('/api/production-stock-requests').subscribe({ next: (data) => { this.stockRequests.set(data); if (showLoading) this.loading.set(false); }, error: (error) => { if (showLoading) this.fail(error); } }); }
  private loadSummary(): void { this.loading.set(true); this.http.get<Paginated<ProductionSummaryRow>>('/api/production-summary', { params: this.params() }).subscribe({ next: (response) => { this.summary.set(response.data); this.loading.set(false); }, error: (error) => this.fail(error) }); }
  protected loadPlantBoard(): void { this.loading.set(true); let params = new HttpParams(); if (this.areaFilter()) params = params.set('productionAreaId', this.areaFilter()!); this.http.get<ProductionConsolidation[]>('/api/production-consolidations/plant', { params }).subscribe({ next: (data) => { this.plantConsolidations.set(data); this.loading.set(false); }, error: (error) => this.fail(error) }); }
  private loadAreas(): void { this.http.get<ProductionArea[]>('/api/production-areas').subscribe({ next: (data) => this.areas.set(data), error: (error) => this.fail(error) }); }
  private loadCategories(): void { this.http.get<ProductCategory[]>('/api/production-areas/categories').subscribe({ next: (data) => this.categories.set(data) }); }
  protected onAreaFilterChange(areaId: string | null): void { this.areaFilter.set(areaId); if (this.categoryFilter() && !this.filterCategories().some((category) => category.id === this.categoryFilter())) this.categoryFilter.set(null); }
  protected filterCategories(): ProductCategory[] { const areaId = this.areaFilter(); if (!areaId) return this.categories(); const ids = new Set(this.areas().find((area) => area.id === areaId)?.categories.map((category) => category.id) ?? []); return this.categories().filter((category) => ids.has(category.id)); }
  protected openGeneration(): void { this.generationForm.reset({ deliveryDate: this.dateFilter() }); this.generationDialog.set(true); }
  protected generate(): void { if (this.generationForm.invalid) return this.generationForm.markAllAsTouched(); this.saving.set(true); const raw = this.generationForm.getRawValue(); this.http.post<ProductionConsolidation>('/api/production-consolidations', { deliveryDate: raw.deliveryDate }).subscribe({ next: (item) => { this.saving.set(false); this.generationDialog.set(false); this.saved('Orden de Producción generada', `${item.details.length} presentaciones planificadas`); this.selected.set(item); this.detailDialog.set(true); this.loadConsolidations(); }, error: (error) => this.failSave(error) }); }
  protected openRequestGeneration(request: StockReplenishmentRequest): void { this.selectedStockRequest.set(request); this.requestGenerationForm.reset({ deliveryDate: request.requiredDate }); this.requestGenerationDialog.set(true); }
  protected generateFromRequest(): void { const request = this.selectedStockRequest(); if (!request || this.requestGenerationForm.invalid) return this.requestGenerationForm.markAllAsTouched(); this.saving.set(true); const { deliveryDate } = this.requestGenerationForm.getRawValue(); this.http.post<ProductionConsolidation>('/api/production-consolidations', { deliveryDate, stockRequestId: request.id }).subscribe({ next: (item) => { this.saving.set(false); this.requestGenerationDialog.set(false); this.selectedStockRequest.set(null); this.view.set('planning'); this.planningPage.set(1); this.selected.set(item); this.detailDialog.set(true); this.saved('Solicitud aceptada y orden generada', `Solicitud ${request.code} · entrega ${this.formatDate(deliveryDate, false)} · ${item.details.length} productos`); this.loadStockRequests(false); this.loadConsolidations(); }, error: (error) => this.failSave(error) }); }
  protected requestAreas(request: StockReplenishmentRequest): string { return [...new Set(request.details.map((detail) => detail.productionArea?.name || 'Sin área'))].join(', '); }
  protected orderStockRequest(item: ProductionConsolidation): Pick<StockReplenishmentRequest, 'id' | 'code' | 'requiredDate' | 'status'> | null { return item.details.find((detail) => detail.stockRequestDetail)?.stockRequestDetail?.request ?? null; }
  protected openDetail(item: ProductionConsolidation): void { this.http.get<ProductionConsolidation>(`/api/production-consolidations/${item.id}`).subscribe({ next: (value) => { this.selected.set(value); this.detailDialog.set(true); }, error: (error) => this.fail(error) }); }
  protected recalculate(item: ProductionConsolidation): void { this.action(`/api/production-consolidations/${item.id}/recalculate`, 'Pedidos y solicitud de stock recalculados'); }
  protected emit(item: ProductionConsolidation): void { this.action(`/api/production-consolidations/${item.id}/emit`, 'Orden emitida a planta'); }
  private action(path: string, message: string): void { this.saving.set(true); this.http.post<ProductionConsolidation>(path, {}).subscribe({ next: (value) => { this.saving.set(false); this.selected.set(value); this.saved(message, `Versión ${value.version}`); this.loadConsolidations(); }, error: (error) => this.failSave(error) }); }
  protected openPlanAdjustment(detail: ProductionConsolidationDetail): void { this.selectedDetail.set(detail); this.planForm.reset({ scheduledDate: detail.scheduledDate, sequence: detail.sequence, additionalQuantity: Number(detail.additionalProductionQuantity), reason: detail.additionalProductionReason ?? '' }); this.planDialog.set(true); }
  protected productionBase(detail: ProductionConsolidationDetail): string { return this.number(Number(detail.productionRequiredQuantity) + Number(detail.stockRequestedQuantity)); }
  protected plannedPreview(): string { return this.number(Number(this.selectedDetail()?.productionRequiredQuantity ?? 0) + Number(this.selectedDetail()?.stockRequestedQuantity ?? 0) + Number(this.planForm.controls.additionalQuantity.value ?? 0)); }
  protected savePlanAdjustment(): void { const item = this.selected(); const detail = this.selectedDetail(); if (!item || !detail || this.planForm.invalid) return this.planForm.markAllAsTouched(); const raw = this.planForm.getRawValue(); if (raw.additionalQuantity > 0 && raw.reason.trim().length < 5) { this.planForm.controls.reason.setErrors({ minlength: true }); return this.planForm.controls.reason.markAsTouched(); } this.saving.set(true); this.http.patch<ProductionConsolidation>(`/api/production-consolidations/${item.id}/details/${detail.id}/schedule`, { scheduledDate: raw.scheduledDate, sequence: raw.sequence, additionalQuantity: raw.additionalQuantity, reason: raw.reason || undefined }).subscribe({ next: (value) => { this.saving.set(false); this.planDialog.set(false); this.selected.set(value); this.saved('Programación actualizada', detail.product.name); this.loadConsolidations(); }, error: (error) => this.failSave(error) }); }
  protected plantGroups(): PlantGroup[] { const groups = new Map<string, { key: string; area: string; rows: PlantRow[]; orderIds: Set<string> }>(); const selectedAreaId = this.areaFilter(); for (const order of this.plantConsolidations()) { for (const detail of order.details) { if (selectedAreaId && detail.productionAreaId !== selectedAreaId) continue; const area = detail.productionArea?.name ?? 'Sin área'; const key = detail.productionAreaId ?? 'none'; const group = groups.get(key) ?? { key, area, rows: [], orderIds: new Set<string>() }; group.rows.push({ order, detail }); group.orderIds.add(order.id); groups.set(key, group); } } return [...groups.values()].sort((left, right) => left.area.localeCompare(right.area)).map((group) => ({ key: group.key, area: group.area, rows: group.rows.sort((left, right) => right.order.code - left.order.code || left.detail.scheduledDate.localeCompare(right.detail.scheduledDate) || left.detail.sequence - right.detail.sequence), orderCount: group.orderIds.size })); }
  protected isFirstOrderRow(group: PlantGroup, row: PlantRow): boolean { return group.rows.find((candidate) => candidate.order.id === row.order.id)?.detail.id === row.detail.id; }
  protected orderHasPendingReceipt(order: ProductionConsolidation): boolean { return order.details.some((detail) => detail.stage === 'PENDIENTE_RECEPCION'); }
  protected openProductionClose(order: ProductionConsolidation): void { this.selected.set(order); this.openReason('incomplete'); }
  protected startProduct(detail: ProductionConsolidationDetail): void { this.saving.set(true); this.http.post<ProductionConsolidation>(`/api/production-consolidations/${detail.consolidationId}/details/${detail.id}/start`, {}).subscribe({ next: (value) => { this.saving.set(false); this.updatePlantOrder(value); this.saved('Producción iniciada', detail.product.name); this.loadPlanningCount(); }, error: (error) => this.failSave(error) }); }
  protected openDelivery(detail: ProductionConsolidationDetail): void { this.selectedDetail.set(detail); const pending = Math.max(Number(detail.plannedQuantity) - Number(detail.preparedQuantity), 0); this.deliveryForm.reset({ quantity: pending, incident: '' }); this.deliveryDialog.set(true); }
  private deliveryAccumulated(detail: ProductionConsolidationDetail): number { const factor = 10 ** detail.baseUnit.decimalScale; return Math.round((Number(detail.preparedQuantity) + Number(this.deliveryForm.controls.quantity.value)) * factor) / factor; }
  protected deliveryWillBeFinal(): boolean { const detail = this.selectedDetail(); return !!detail && this.deliveryAccumulated(detail) >= Number(detail.plannedQuantity); }
  protected deliveryResultMessage(): string { const detail = this.selectedDetail(); if (!detail) return ''; const accumulated = this.deliveryAccumulated(detail); if (accumulated < Number(detail.plannedQuantity)) return `Entrega parcial. Quedarán ${this.number(Number(detail.plannedQuantity) - accumulated)} pendientes y, después de la recepción de Almacén, se habilitará nuevamente Entregar.`; if (accumulated === Number(detail.plannedQuantity)) return 'Esta entrega completa el plan y se registrará como entrega final.'; return `Esta entrega supera el plan en ${this.number(accumulated - Number(detail.plannedQuantity))}; debe registrar el motivo del excedente.`; }
  protected deliver(): void { const detail = this.selectedDetail(); if (!detail || this.deliveryForm.invalid) return this.deliveryForm.markAllAsTouched(); const raw = this.deliveryForm.getRawValue(); const finalDelivery = this.deliveryAccumulated(detail) >= Number(detail.plannedQuantity); this.saving.set(true); this.http.post<ProductionConsolidation>(`/api/production-consolidations/${detail.consolidationId}/details/${detail.id}/deliveries`, { quantity: raw.quantity, finalDelivery, incident: raw.incident || undefined }).subscribe({ next: (value) => { this.saving.set(false); this.deliveryDialog.set(false); this.updatePlantOrder(value); this.saved(finalDelivery ? 'Entrega final enviada a Almacén' : 'Entrega parcial enviada a Almacén', detail.product.name); this.loadPlanningCount(); }, error: (error) => this.failSave(error) }); }
  protected openReason(action: ReasonAction, detail?: ProductionConsolidationDetail): void { this.reasonAction.set(action); this.selectedDetail.set(detail ?? null); this.reasonForm.reset({ reason: '' }); this.reasonDialog.set(true); }
  protected reasonTitle(): string { return this.reasonAction() === 'detail' ? 'Cancelar producto' : this.reasonAction() === 'order' ? 'Cancelar orden de Producción' : 'Completar producción con faltantes'; }
  protected reasonButtonLabel(): string { return this.reasonAction() === 'incomplete' ? 'Completar producción' : 'Confirmar cancelación'; }
  protected submitReason(): void { const action = this.reasonAction(); const detail = this.selectedDetail(); const item = action === 'detail' && detail ? this.plantConsolidations().find((order) => order.id === detail.consolidationId) ?? this.selected() : this.selected(); if (!item || this.reasonForm.invalid || (action === 'detail' && !detail)) return this.reasonForm.markAllAsTouched(); const path = action === 'detail' ? `/api/production-consolidations/${item.id}/details/${detail!.id}/cancel` : action === 'order' ? `/api/production-consolidations/${item.id}/cancel` : `/api/production-consolidations/${item.id}/close-incomplete`; this.saving.set(true); this.http.post<ProductionConsolidation>(path, this.reasonForm.getRawValue()).subscribe({ next: (value) => { this.saving.set(false); this.reasonDialog.set(false); if (action === 'detail') this.updatePlantOrder(value); if (this.selected()?.id === value.id) this.selected.set(value); this.saved(action === 'incomplete' ? 'Orden completada con faltantes' : action === 'order' ? 'Orden cancelada' : 'Producto cancelado', this.reasonForm.controls.reason.value); if (this.view() === 'plant') this.loadPlantBoard(); else this.loadConsolidations(); this.loadStockRequests(false); }, error: (error) => this.failSave(error) }); }
  private updatePlantOrder(value: ProductionConsolidation): void { this.plantConsolidations.update((orders) => orders.map((order) => order.id === value.id ? value : order).filter((order) => order.status === 'EMITIDA' || order.status === 'EN_PROCESO')); }
  protected openArea(area?: ProductionArea): void { this.editingAreaId.set(area?.id ?? null); this.areaForm.reset({ name: area?.name ?? '', status: area?.status ?? 'ACTIVO', categoryIds: area?.categories.map((category) => category.id) ?? [] }); this.areaDialog.set(true); }
  protected availableAreaCategories(): ProductCategory[] { const currentAreaId = this.editingAreaId(); const unavailable = new Set(this.areas().filter((area) => area.id !== currentAreaId).flatMap((area) => area.categories.map((category) => category.id))); return this.categories().filter((category) => category.status === 'ACTIVO' && !unavailable.has(category.id)); }
  protected saveArea(): void { if (this.areaForm.invalid) return this.areaForm.markAllAsTouched(); const raw = this.areaForm.getRawValue(); const id = this.editingAreaId(); this.saving.set(true); const request = id ? this.http.patch<ProductionArea>(`/api/production-areas/${id}`, raw) : this.http.post<ProductionArea>('/api/production-areas', { name: raw.name, categoryIds: raw.categoryIds }); request.subscribe({ next: () => { this.saving.set(false); this.areaDialog.set(false); this.saved('Área guardada', raw.name); this.loadAreas(); }, error: (error) => this.failSave(error) }); }
  protected openHistory(item: ProductionConsolidation): void { this.http.get<ProductionHistory[]>(`/api/production-consolidations/${item.id}/history`).subscribe({ next: (events) => { this.history.set(events); this.historyDialog.set(true); }, error: (error) => this.fail(error) }); }
  protected detailTitle(): string { const item = this.selected(); return item ? `Planificación · orden ${item.code}` : 'Planificación'; }
  protected severity(status: ProductionConsolidationStatus): 'info' | 'warn' | 'success' | 'secondary' | 'danger' { return status === 'CERRADA' ? 'success' : status === 'CANCELADA' ? 'danger' : status === 'CERRADA_INCOMPLETA' || status === 'EN_PROCESO' ? 'warn' : status === 'EMITIDA' ? 'info' : 'secondary'; }
  protected stageSeverity(stage: ProductionDetailStage): 'info' | 'warn' | 'success' | 'secondary' | 'danger' { return stage === 'COMPLETADO' ? 'success' : stage === 'CERRADO_CON_INCIDENCIA' || stage === 'CANCELADO' ? 'danger' : stage === 'PENDIENTE_RECEPCION' ? 'warn' : stage === 'EN_PROCESO' || stage === 'RECIBIDO_PARCIAL' ? 'info' : 'secondary'; }
  protected stageLabel(stage: ProductionDetailStage): string { return ({ PENDIENTE: 'Pendiente', EN_PROCESO: 'En proceso', PENDIENTE_RECEPCION: 'Pendiente recepción', RECIBIDO_PARCIAL: 'Recibido parcial', COMPLETADO: 'Completado', CERRADO_CON_INCIDENCIA: 'Completado con incidencia', CANCELADO: 'Cancelado' } as Record<ProductionDetailStage, string>)[stage]; }
  protected remainingQuantity(detail: ProductionConsolidationDetail): number { return Math.max(Number(detail.plannedQuantity) - Number(detail.preparedQuantity), 0); }
  protected deliveryStatusLabel(status: ProductionDelivery['status']): string { return status === 'ACEPTADA' ? 'Recibida por Almacén' : 'Pendiente de recepción'; }
  protected isPreparationOverdue(item: ProductionConsolidation): boolean { return !!item.preparationDeadlineAt && item.status === 'BORRADOR' && new Date(item.preparationDeadlineAt).getTime() < Date.now(); }
  protected statusLabel(status: ProductionConsolidationStatus): string { return ({ BORRADOR: 'Borrador', EMITIDA: 'Emitida', EN_PROCESO: 'En proceso', CERRADA: 'Completada', CERRADA_INCOMPLETA: 'Completada con faltantes', CANCELADA: 'Cancelada' } as Record<ProductionConsolidationStatus, string>)[status]; }
  protected formatShortDate(value: string | null): string { if (!value) return '—'; return new Intl.DateTimeFormat('es-BO', { day: '2-digit', month: '2-digit', year: '2-digit' }).format(new Date(value.length === 10 ? `${value}T12:00:00` : value)); }
  protected formatPlantMoment(value: string | null): string { if (!value) return '—'; return new Intl.DateTimeFormat('es-BO', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(value)); }
  protected formatDate(value: string | null, withTime: boolean): string { if (!value) return '—'; return new Intl.DateTimeFormat('es-BO', withTime ? { dateStyle: 'medium', timeStyle: 'short' } : { dateStyle: 'medium' }).format(new Date(value.length === 10 ? `${value}T12:00:00` : value)); }
  protected number(value: string | number): string { return new Intl.NumberFormat('es-BO', { maximumFractionDigits: 6 }).format(Number(value)); }
  protected numberValue(value: string | number): number { return Number(value); }
  protected total(key: keyof Pick<ProductionSummaryRow, 'requestedQuantity' | 'warehouseCoveredQuantity' | 'productionRequiredQuantity' | 'stockRequestedQuantity' | 'additionalProductionQuantity' | 'plannedQuantity' | 'preparedQuantity' | 'receivedQuantity' | 'pendingQuantity' | 'difference'>): string { return this.number(this.summary().reduce((sum, row) => sum + Number(row[key]), 0)); }
  private saved(summary: string, detail: string): void { this.messages.add({ severity: 'success', summary, detail }); }
  private fail(error: unknown): void { this.loading.set(false); this.messages.add({ severity: 'error', summary: 'No se pudo cargar Producción', detail: this.error(error) }); }
  private failSave(error: unknown): void { this.saving.set(false); this.messages.add({ severity: 'error', summary: 'No se pudo completar la operación', detail: this.error(error) }); }
  private error(error: unknown): string { if (!(error instanceof HttpErrorResponse)) return 'Error inesperado'; const message = error.error?.message; return Array.isArray(message) ? message.join('. ') : message || 'La solicitud no pudo completarse'; }
}
